Error: TypeError: Cannot destructure property 'user' of 'undefined'

Stack trace:
  at AuthContext (src/context/AuthContext.tsx:18)
  at useAuth (src/hooks/useAuth.ts:5)

Code:
```typescript
const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [state, setState] = useState({ user: null, loading: true });

  return (
    <AuthContext.Provider value={state}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const { user, loading } = useContext(AuthContext);
  return { user, loading };
}
```

expected:
## Root Cause Analysis

**Issue**: Context used outside Provider. `useContext(AuthContext)` returns `undefined` when the component is not wrapped in `AuthProvider`, causing destructuring to fail.

**Root Cause Category**: context_outside_provider

## Fix
```typescript
// Add default value to createContext
const AuthContext = createContext<AuthState | undefined>(undefined);

export function useAuth() {
  const context = useContext(AuthContext);

  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }

  return context;
}

// Ensure Provider wraps the app
// In App.tsx or _app.tsx:
function App() {
  return (
    <AuthProvider>
      <Router>
        {/* routes */}
      </Router>
    </AuthProvider>
  );
}
```

## Verification
- Clear error message when used outside provider
- Provider wraps entire app
- TypeScript types enforce proper usage

