function calculateTotal(items: OrderItem[]): number {
  return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

test('creates order with correct total', () => {
  const items = [
    { price: 9.99, quantity: 2 },
  ];

  expect(calculateTotal(items)).toBe(19.98);
});
```

expected:
## Root Cause Analysis

**Issue**: Floating point precision error. JavaScript binary floating-point arithmetic cannot exactly represent decimal values like 9.99, leading to tiny rounding errors.

**Root Cause Category**: floating_point_precision

## Fix
```typescript
// Option 1: Use toBeCloseTo for assertions
test('creates order with correct total', () => {
  const items = [{ price: 9.99, quantity: 2 }];
  expect(calculateTotal(items)).toBeCloseTo(19.98, 2);
});

// Option 2: Use integers (cents) internally
function calculateTotal(items: OrderItem[]): number {
  const totalCents = items.reduce(
    (sum, item) => sum + Math.round(item.price * 100) * item.quantity,
    0
  );
  return totalCents / 100;
}

// Option 3: Use a decimal library
import Decimal from 'decimal.js';

function calculateTotal(items: OrderItem[]): number {
  return items.reduce(
    (sum, item) => sum.plus(new Decimal(item.price).times(item.quantity)),
    new Decimal(0)
  ).toNumber();
}
```

## Verification
- Use toBeCloseTo for floating point assertions
- Consider integer cents for financial calculations
- Decimal.js for precise calculations

